-- One more FAQ (17 November 2026): what a car with driver costs in Madrid, a question people search
-- for. A new entry only: an entry that already exists under the same address is left alone.
INSERT INTO "content_entries" ("collection", "slug", "sort_order", "data")
VALUES ('faq', 'car-with-driver-cost', 150, '{"featured":true,"question":{"en":"How much does a car with driver cost in Madrid?","es":"¿Cuánto cuesta un coche con conductor en Madrid?"},"answer":{"en":"It depends on the vehicle and the journey. A transfer within the M-30 ring, or between Madrid–Barajas airport and the M-30, has a fixed starting price for each vehicle, shown on the fleet page; further out, a rate per kilometre is added for the distance beyond the M-30. Hourly hire is priced per hour, from two hours; for some vehicles the hourly price is agreed with you. The booking form shows the exact price, VAT included, before you confirm.","es":"Depende del vehículo y del trayecto. Un traslado dentro de la M-30, o entre el aeropuerto de Madrid–Barajas y la M-30, tiene un precio de salida fijo para cada vehículo, que puede ver en la página de la flota; más allá, se añade una tarifa por kilómetro por la distancia fuera de la M-30. El servicio por horas se factura por hora, desde dos horas; en algunos vehículos el precio por hora se acuerda con usted. El formulario de reserva muestra el precio exacto, con IVA incluido, antes de confirmar."}}')
ON CONFLICT ("collection", "slug") DO NOTHING;
